// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 warpBase, address actor) public {
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.roll(1); // fix block.difficulty so randomness depends only on timestamp and sender
        warpBase = bound(warpBase, 1, type(uint256).max / 2);

        // find a timestamp t0 where the drawn bit is 0
        uint256 t0 = 0;
        for (uint256 t = warpBase; t < warpBase + 500; t++) {
            if (uint(keccak256(abi.encodePacked(t, block.difficulty, actor))) % 2 == 0) {
                t0 = t;
                break;
            }
        }
        vm.assume(t0 != 0);

        // find a later timestamp t1 where the drawn bit is 1
        uint256 t1 = 0;
        for (uint256 t = t0 + 1; t < t0 + 500; t++) {
            if (uint(keccak256(abi.encodePacked(t, block.difficulty, actor))) % 2 == 1) {
                t1 = t;
                break;
            }
        }
        vm.assume(t1 != 0);

        vm.deal(actor, 2 * 10); // two tickets

        // play 1: bit 0 -> reference pays out and resets pot; mutant keeps pot at 10
        vm.warp(t0);
        vm.prank(actor);
        c.play{value: 10}();

        // play 2: bit 1 -> reference does nothing (pot stays 10); mutant pays out and resets pot to 0
        vm.warp(t1);
        vm.prank(actor);
        c.play{value: 10}();

        // after the (0,1) bit sequence, the correct contract leaves the pot at TICKET_AMOUNT
        assertTrue(c.pot() == 10);
    }
}

