pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // the test contract is C's bank (deployer); it must accept the fee transfer
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 ts) public {
        // admissible domain: a plain EOA player, an arbitrary but sane block timestamp
        vm.assume(actor != address(0) && actor != address(this) && actor.code.length == 0);
        vm.warp(bound(ts, 1, type(uint64).max));

        // ticket price is fixed by C (TICKET_AMOUNT = 10 wei)
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // recompute the same draw C used (same block context, same sender)
        uint256 bit = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        // RULE: pot is empty AND bank holds exactly the fee  <=>  drawn bit == 0;
        //        otherwise the ticket (10 wei) still sits in the pot.
        assertTrue(
            bit == 0
                ? (c.pot() == 0 && address(c).balance == 1)
                : (c.pot() == 10 && address(c).balance == 0)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint amt) public {
        require(amt == 10);
        require(address(this).balance >= amt);
        bool ok;
        (ok, ) = address(c).call{value: amt}(abi.encodeWithSignature("play()"));
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function f() external payable {
        require(address(this).balance >= 20);

        uint b0 = address(this).balance;
        c.play{value: 10}();
        uint d1 = address(this).balance - b0; // 9 iff first play won (10-1)

        uint b1 = address(this).balance;
        c.play{value: 10}();
        uint d2 = address(this).balance - b1; // payout of second play if it won

        // If the first play won (draining the pot) and the second play also won,
        // the second payout must be exactly 9 (fresh pot). In M the stale pot
        // makes the second win pay 19.
        assert(!(d1 == 9 && d2 > 0) || d2 == 9);
    }
}

